#!/usr/bin/env python3
"""
Modern Climate Data Analysis Script - Python 3
Replaces the legacy Python 2.7 version at climate_analyzer/analyze_climate.py.
"""

import configparser
from pathlib import Path

import numpy as np
import pandas as pd


class ClimateAnalyzer:
    """Loads and analyzes climate temperature data from CSV files."""

    def __init__(self, config_path: str = "config.ini") -> None:
        self.config = configparser.ConfigParser()
        # configparser handles UTF-8 transparently on Python 3
        self.config.read(config_path, encoding="utf-8")
        self.data_cache: dict = {}

    def load_temperature_data(self, csv_path: Path) -> pd.DataFrame:
        """Load temperature data from a UTF-8 CSV file using modern pandas API."""
        df = pd.read_csv(
            csv_path,
            parse_dates=["date"],
            encoding="utf-8",
        )
        # Python 3 strings are Unicode natively — no extra conversion needed
        return df

    def calculate_mean_temperatures(self, df: pd.DataFrame) -> pd.Series:
        """Calculate mean temperature per station using vectorised NumPy."""
        # Modern pandas groupby aggregation — no xrange or manual loops
        return df.groupby("station_id")["temperature"].mean()

    def run_analysis(self, csv_path: Path) -> None:
        """Main analysis pipeline: load data and report mean temperatures."""
        print("Starting climate analysis...")

        try:
            data = self.load_temperature_data(csv_path)
        except FileNotFoundError:
            print(f"Error: data file not found at {csv_path}")
            raise
        except pd.errors.EmptyDataError:
            print(f"Error: data file at {csv_path} is empty")
            raise

        # Vectorised per-station mean — no deprecated iteritems()
        means = self.calculate_mean_temperatures(data)

        for station_id in sorted(means.index):
            temp = means[station_id]
            print(f"Station {station_id} mean temperature: {temp:.1f}°C")

        print("Analysis completed successfully!")


if __name__ == "__main__":
    # Resolve CSV path relative to this script using pathlib
    script_dir = Path(__file__).resolve().parent
    default_csv = script_dir / "climate_analyzer" / "sample_data" / "climate_data.csv"

    # Try to read config for an alternative path, fall back to default
    try:
        analyzer = ClimateAnalyzer()
        config_path = analyzer.config.get(
            "analysis", "output_path", fallback=None
        )
        if config_path:
            csv_path = Path(config_path).parent / "climate_data.csv"
            if not csv_path.exists():
                csv_path = default_csv
        else:
            csv_path = default_csv
    except Exception:
        csv_path = default_csv

    analyzer.run_analysis(csv_path)

